const DEFAULT = 'https://api.example.invalid';
function createClient(creds) {
  const config = { privateKey: creds.privateKey, timeout: 30000, apiKey: creds.apiKey };
  return {
    call(path, body) {
      return fetch(DEFAULT + path, {
        method: 'POST',
        body: JSON.stringify(body),
        headers: { 'x-api-key': config.apiKey },
        timeout: config.timeout,
      });
    },
  };
}
module.exports = { createClient };

